const cfg = $('Config1').first().json;
const sd = $getWorkflowStaticData('global');
sd.posted = sd.posted || [];
let url = cfg.FORCE_URL;
if (!url) {
  const xml = $input.first().json.data || '';
  const all = [...xml.matchAll(/<(?:loc|link)>\s*(?:<!\[CDATA\[)?\s*(https?:\/\/[^<\s\]]+)/g)].map(m => m[1]);
  const re = new RegExp(cfg.URL_INCLUDE);
  const fresh = [...new Set(all)].filter(u => re.test(u) && !u.endsWith('.xml') && !sd.posted.includes(u));
  if (!fresh.length) throw new Error('No unposted candidate URLs found (check INDEX_URL / URL_INCLUDE)');
  url = fresh[Math.floor(Math.random() * fresh.length)]; // random => content variety
}
return [{json:{url}}];

const html = $input.first().json.data || '';
const url = $('Parse & Select1').first().json.url;
const dec = s => (s||'').replace(/&#x([0-9a-f]+);/gi,(m,h)=>String.fromCharCode(parseInt(h,16))).replace(/&#(\d+);/g,(m,n)=>String.fromCharCode(+n)).replace(/&amp;/g,'&').replace(/&#39;|&#x27;/g,"'").replace(/&quot;/g,'"').replace(/&lt;/g,'<').replace(/&gt;/g,'>').trim();
const meta = p => {
  const a = html.match(new RegExp('<meta[^>]+(?:property|name)=["\']'+p+'["\'][^>]*content=["\']([^"\']*)["\']','i'));
  const b = html.match(new RegExp('<meta[^>]+content=["\']([^"\']*)["\'][^>]+(?:property|name)=["\']'+p+'["\']','i'));
  return dec((a||b||[])[1]);
};
const title = meta('og:title') || dec((html.match(/<title[^>]*>([^<]*)/i)||[])[1]);
const summary = meta('og:description') || meta('description');
let image = meta('og:image'); if (image && image.startsWith('/')) image = new URL(image, url).href;
const body = dec(html.replace(/<!--[\s\S]*?-->/g,' ').replace(/<(script|style|nav|header|footer|noscript)[\s\S]*?<\/\1>/gi,' ').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ')).slice(0,4000);
if (body.length < 200 && summary.length < 50) throw new Error('Page had too little text: ' + url);
return [{json:{url,title,summary,image,body}}];

const cfg = $('Config1').first().json; const src = $('Build Generate Request1').first().json;
const raw = ((($input.first().json.candidates||[])[0]||{}).content?.parts||[]).map(p=>p.text||'').join('').replace(/```json|```/g,'').trim();
let p; try { p = JSON.parse(raw); } catch(e) { throw new Error('LLM returned non-JSON: ' + raw.slice(0,200)); }
if (cfg.DEMO_BAD_POST) p.lines = [...(p.lines||[]), 'Prices start at $999 and results are guaranteed.']; // DEMO ONLY
const tags = (p.hashtags||[]).map(t=>t.startsWith('#')?t:'#'+t);
const pre = [p.hook, ...(p.lines||[]), p.cta].join('\n');
const post = `${p.hook}\n\n${(p.lines||[]).join('\n')}\n\n${p.cta}\n${src.url}\n\n${tags.join(' ')}`;
const sourceText = (src.title+' '+src.summary+' '+src.body).toLowerCase();
const issues = [];
if (pre.length > 500) issues.push('Too long: '+pre.length);
if ((p.lines||[]).length < 2 || p.lines.length > 4) issues.push('Need 2-4 value lines');
if (tags.length < 3 || tags.length > 5) issues.push('Need 3-5 hashtags');
const banned = /\b(cures?|cured|guarantee[sd]?|100%|risk[- ]free|painless|no side effects|permanent(ly)?|miracle|enhanc\w*|maximi[sz]\w*|improv\w*|boost\w*|success\w*|benefits?|effective\w*|expert|leading|breakthrough|advanced|helps? (maintain|preserve|reduce|relieve|restore)|best|safest|safe|proven|will (help|improve|restore|fix|heal)|results? (in|within))\b/i;
const m = pre.match(banned); if (m) issues.push('Banned claim wording: '+m[0]);
if (/[$€£]\s?\d|\d\s?(usd|eur|dollars|euros)/i.test(pre) && !/[$€£]\s?\d/.test(src.body+src.summary)) issues.push('Price not in source');
for (const n of (pre.match(/\d[\d,.]*/g)||[])) if (!sourceText.includes(n.replace(/[.,]$/,''))) issues.push('Number not in source: '+n);
const verifyReq = {
 systemInstruction:{parts:[{text:'You are a strict compliance reviewer for medical-tourism marketing. Return ONLY JSON: {"pass": boolean, "issues": [string]}. Fail if the POST contains any medical claim, promise/implied guarantee of outcomes, price, statistic, or fact not supported by the SOURCE.'}]},
 contents:[{role:'user',parts:[{text:`SOURCE:\n${src.title}\n${src.summary}\n${src.body}\n\nPOST:\n${pre}`}]}],
 generationConfig:{responseMimeType:'application/json', temperature:0, maxOutputTokens:500, thinkingConfig:{thinkingBudget:0}}};
return [{json:{post, ruleIssues:issues, url:src.url, title:src.title, image:src.image, request:verifyReq}}];

const r = $('Guardrails Rules1').first().json;
const raw = ((($input.first().json.candidates||[])[0]||{}).content?.parts||[]).map(p=>p.text||'').join('').replace(/```json|```/g,'').trim();
let v; try { v = JSON.parse(raw); } catch(e) { v = {pass:false, issues:['Verifier returned non-JSON']}; }
const issues = [...r.ruleIssues, ...(v.pass ? [] : (v.issues||['LLM verifier failed']))];
return [{json:{passed: issues.length===0, issues, post:r.post, url:r.url, title:r.title, image:r.image}}];

