const g = $('Gate1').first().json; const cfg = $('Config1').first().json;
const params = g.image ? {url:g.image, caption:g.post} : {message:g.post, link:g.url};
if (cfg.SCHEDULE_HOURS_AHEAD > 0) { params.published = false; params.scheduled_publish_time = Math.floor(Date.now()/1000 + cfg.SCHEDULE_HOURS_AHEAD*3600); }
if (cfg.DEMO_FB_FAIL) params.access_token = 'DEMO_INVALID_TOKEN'; // DEMO ONLY: forces an OAuth error, posts nothing
return [{json:{endpoint: g.image ? 'photos' : 'feed', params, dryRun: cfg.DRY_RUN && !cfg.DEMO_FB_FAIL, pageId: cfg.FB_PAGE_ID}}];

const g = $('Gate1').first().json; const cfg = $('Config1').first().json; const r = $input.first().json;
const sd = $getWorkflowStaticData('global'); sd.posted = sd.posted||[]; sd.log = sd.log||[];
const entry = {ts:new Date().toISOString(), url:g.url, title:g.title, post:g.post, fbPostId:r.post_id||r.id, status:r.simulated?'simulated':(cfg.SCHEDULE_HOURS_AHEAD>0?'scheduled':'published'), approval:cfg.APPROVAL_MODE};
if (!r.simulated) sd.posted.push(g.url);   // only mark as used after a real publish
sd.log.push(entry); sd.log = sd.log.slice(-200);
return [{json:entry}];

const sd = $getWorkflowStaticData('global'); sd.log = sd.log || [];
const j = $input.first().json; const ts = new Date().toISOString();
let subject, text, status, url = '', post = '', err = '';
if (j.execution) {                       // Error Trigger (automatic/production runs)
  err = (j.execution.error && j.execution.error.message) || '';
  subject = '[ALERT] Workflow failed: ' + j.workflow.name; status = 'error';
  text = `Node: ${j.execution.lastNodeExecuted}\nError: ${err}\nExecution: ${j.execution.url}`;
} else if (Array.isArray(j.issues)) {    // guardrail block
  url = j.url; post = j.post; status = 'blocked'; err = j.issues.join('; ');
  subject = '[ALERT] Post blocked by guardrails';
  text = `URL: ${url}\nIssues:\n- ${j.issues.join('\n- ')}\n\nDraft (NOT posted):\n${post}`;
} else {                                 // node error output (works in manual runs too)
const order = ['Fetch Index1','Pick Child Sitemap1','Fetch Child Sitemap1','Parse & Select1','Fetch Page1','Extract Page1','LLM Generate1','Guardrails Rules1','LLM Verify1','Publish to Facebook1'];
let failed = 'unknown';
  for (const n of order) { try { if ($(n).isExecuted) failed = n; } catch (e) {} }
  err = j.error ? (typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error))) : JSON.stringify(j).slice(0, 500);
  err = err.slice(0, 600); status = 'error';
  subject = '[ALERT] Step failed: ' + failed;
  text = `Failed step: ${failed}\nError: ${err}\nExecution ID: ${$execution.id}\n\nNothing was posted.`;
}
sd.log.push({ts, url, post, fbPostId: null, status, error: err}); sd.log = sd.log.slice(-200);
return [{json:{subject, text}}];

const cfg = $('Config1').first().json;
const xml = $input.first().json.data || '';
const locs = [...xml.matchAll(/<loc>\s*(https?:\/\/[^<\s]+)\s*<\/loc>/g)].map(m => m[1]);
const pool = cfg.CONTENT_SITEMAPS.map(w => locs.find(l => l.includes(w))).filter(Boolean);
if (!pool.length) throw new Error('None of CONTENT_SITEMAPS found in sitemap index');
const day = Math.floor(Date.now() / 86400000);
return [{json:{child: pool[day % pool.length]}}];   // rotate content type daily (variety stretch goal)
